args<-commandArgs(FALSE);root<-normalizePath(file.path(dirname(sub('^--file=','',args[grepl('^--file=',args)])),'..'))
.libPaths(c(file.path(root,'work/Rlib'),.libPaths()))
suppressPackageStartupMessages(library(slingshot))
x<-read.csv(file.path(root,'results/spatial_trajectory_input.csv'),row.names=1,check.names=FALSE)
coords<-as.matrix(x[,c('UMAP1','UMAP2')]);cl<-factor(x$region)
set.seed(20261114)
a<-slingshot(coords,clusterLabels=cl,start.clus='Non Damaged sites/Lesion')
b<-slingshot(coords,clusterLabels=cl,start.clus='Damaged sites(Core)')
o<-data.frame(spot=rownames(x),region=x$region,non_damaged_root=slingPseudotime(a)[,1],damaged_root=slingPseudotime(b)[,1])
write.csv(o,file.path(root,'results/spatial_alternative_orderings.csv'),row.names=FALSE)
curves<-list();for (nm in c('non_damaged','damaged')) {q<-if(nm=='non_damaged')a else b;cu<-slingCurves(q)[[1]];curves[[nm]]<-data.frame(orientation=nm,UMAP1=cu$s[cu$ord,1],UMAP2=cu$s[cu$ord,2])}
write.csv(do.call(rbind,curves),file.path(root,'results/spatial_principal_curves.csv'),row.names=FALSE)
write.csv(data.frame(slingshot=as.character(packageVersion('slingshot')),n_spots=nrow(x),n_sections=1,root_spearman=cor(o$non_damaged_root,o$damaged_root,method='spearman',use='complete.obs'),scope='Revision refit on saved 1068-spot UMAP; not reproduction of an archived original Slingshot object'),file.path(root,'results/spatial_root_sensitivity.csv'),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(root,'results/trajectory_R_sessionInfo.txt'))
print(cor(o$non_damaged_root,o$damaged_root,method='spearman',use='complete.obs'))
